'use client';

import { useId, useState } from 'react';

import {
  type AutoplayStep,
  typingSteps,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { keyDelayOf, spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { MAX_VOLUME, type Plan, PLANS, SECTION, START_VOLUME } from './data';
import { PlanCard } from './plan-card';
import {
  cheapestPlanAt,
  clampVolume,
  positionOf,
  volumeAt,
  volumeOfText,
} from './volume-model';
import { VolumeSentence } from './volume-sentence';
import { VolumeTrack } from './volume-track';

/** Where the demonstration drags the volume: past the notch where Scale becomes the cheapest. */
const DEMO_SCRUB_TO = 200_000;

/** What the demonstration then types, back in the stretch where Hobby is the cheapest. */
const DEMO_TYPED = '4500';

/** The pause between two stops when the demonstration drags the number. */
const SCRUB_STEP_MS = 130;

const LOOP_AFTER_MS = 3000;

/** A drag of the demonstration from stop to stop, through the same handler a hand uses. */
function scrubSteps(
  from: number,
  to: number,
  write: (volume: number) => void,
  startAfter: number
): AutoplayStep[] {
  const firstPosition = Math.round(positionOf(from));
  const lastPosition = Math.round(positionOf(to));
  const distance = lastPosition - firstPosition;
  const direction = Math.sign(distance);
  const count = Math.abs(distance);
  const indexes = Array.from({ length: count }, (_, index) => index);
  return indexes.map((index) => {
    const walked = index + 1;
    const offset = walked * direction;
    const position = firstPosition + offset;
    const volume = volumeAt(position);
    const after = keyDelayOf(index, startAfter, SCRUB_STEP_MS);
    return { after, run: () => write(volume) };
  });
}

function announcementOf(cheapest: Plan, isOverLimit: boolean) {
  if (isOverLimit) {
    return SECTION.over;
  }
  return `${cheapest.name} is the cheapest plan at this volume.`;
}

export default function Pricing04() {
  const [volume, setVolume] = useState(START_VOLUME);
  const [draft, setDraft] = useState<string | null>(null);
  const [isOverLimit, setIsOverLimit] = useState(false);
  const [isDemoScrubbing, setIsDemoScrubbing] = useState(false);
  const hintId = useId();
  const cheapest = cheapestPlanAt(volume);

  function type(text: string) {
    setDraft(text);
    const typed = volumeOfText(text);
    if (typed === null) {
      setIsOverLimit(false);
      return;
    }
    const isOver = typed > MAX_VOLUME;
    const next = clampVolume(typed);
    setVolume(next);
    setIsOverLimit(isOver);
  }

  function commit() {
    setDraft(null);
  }

  function scrubTo(next: number) {
    setVolume(next);
    setDraft(null);
    setIsOverLimit(false);
  }

  function startOver() {
    setVolume(START_VOLUME);
    setDraft(null);
    setIsOverLimit(false);
    setIsDemoScrubbing(false);
  }

  const steps: AutoplayStep[] = [
    { after: 1300, run: () => setIsDemoScrubbing(true) },
    ...scrubSteps(START_VOLUME, DEMO_SCRUB_TO, scrubTo, 180),
    { after: 260, run: () => setIsDemoScrubbing(false) },
    { after: 1800, run: () => type('') },
    ...typingSteps(DEMO_TYPED, type, { startAfter: 420, characterMs: 170 }),
    { after: 600, run: commit },
  ];
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: startOver,
  });
  /** A person who takes over in the middle of the drag lets go of the number. */
  const showsDemoScrub = isDemoScrubbing && isAutoplaying;
  const announcement = announcementOf(cheapest, isOverLimit);
  const message = spokenUnless(isAutoplaying, announcement);

  useKeptHeight(ref);

  return (
    <section className='@container'>
      <div
        ref={ref}
        className='mx-auto flex min-h-[44rem] max-w-5xl flex-col gap-10 px-4 py-16 @2xl:gap-12 @2xl:px-6 @2xl:py-24'
      >
        <div className='flex flex-col gap-6'>
          <div className='flex max-w-2xl flex-col gap-3'>
            <h2 className='text-primary-ink text-sm font-medium'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.description}
            </p>
          </div>
          <VolumeSentence
            volume={volume}
            draft={draft}
            isOverLimit={isOverLimit}
            isDemoScrubbing={showsDemoScrub}
            hintId={hintId}
            onType={type}
            onCommit={commit}
            onScrub={scrubTo}
          />
          <VolumeTrack
            volume={volume}
            cheapest={cheapest}
            onVolumeChange={scrubTo}
          />
        </div>
        <div className='grid gap-4 @3xl:grid-cols-3'>
          {PLANS.map((plan) => (
            <PlanCard
              key={plan.id}
              plan={plan}
              volume={volume}
              isCheapest={plan === cheapest}
            />
          ))}
        </div>
        <p className='text-muted-foreground text-xs'>{SECTION.footnote}</p>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';

import { SECTION } from './data';
import {
  formatVolume,
  positionOf,
  stopAbove,
  stopBelow,
  volumeAt,
} from './volume-model';

/** How far the pointer travels to reach the next stop when it drags the number. */
const PX_PER_STOP = 8;

/** Under this distance a press on the number is a click, and the click opens it for typing. */
const DRAG_THRESHOLD_PX = 4;

/** Room for "10,000,000" and one key more: a longer entry would push the sentence past the width of a phone. */
const MAX_TYPED_CHARACTERS = 11;

type DragStart = {
  x: number;
  position: number;
};

function describedByOf(isOverLimit: boolean, hintId: string) {
  if (isOverLimit) {
    return hintId;
  }
  return undefined;
}

function scrubbingOf(isScrubbing: boolean) {
  if (isScrubbing) {
    return 'true';
  }
  return undefined;
}

function isPrimaryPress(event: React.PointerEvent<HTMLInputElement>) {
  return event.button === 0;
}

/** A press let go outside the number never reaches its pointerup: the next move finds no button down. */
function isReleased(event: React.PointerEvent<HTMLInputElement>) {
  return event.buttons === 0;
}

function isFocused(element: HTMLElement) {
  return document.activeElement === element;
}

/** A press on the number while it is not being typed in may become a drag: no caret, no focus yet. */
function keepFocusAway(event: React.MouseEvent<HTMLInputElement>) {
  if (isFocused(event.currentTarget)) {
    return;
  }
  event.preventDefault();
}

type VolumeSentenceProps = {
  volume: number;
  /** What is typed in the number, while a person or the demonstration types; null shows the volume. */
  draft: string | null;
  isOverLimit: boolean;
  /** The demonstration drags the number: it wears the look of a hand on it. */
  isDemoScrubbing: boolean;
  hintId: string;
  onType: (text: string) => void;
  onCommit: () => void;
  onScrub: (volume: number) => void;
};

/**
 * "I expect 12,000 requests a month". The number is a field: drag it sideways to scrub through the
 * stops, click it to type, Up and Down step from stop to stop, Escape puts back what was there.
 * The field takes the width of a hidden copy of its text, so it is given no width of its own.
 */
export function VolumeSentence({
  volume,
  draft,
  isOverLimit,
  isDemoScrubbing,
  hintId,
  onType,
  onCommit,
  onScrub,
}: VolumeSentenceProps) {
  const [isScrubbing, setIsScrubbing] = useState(false);
  const dragStart = useRef<DragStart | null>(null);
  const hasDragged = useRef(false);
  const volumeAtFocus = useRef(volume);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const formatted = formatVolume(volume);
  const shownText = draft ?? formatted;
  const isHandOnNumber = isScrubbing || isDemoScrubbing;

  function startDrag(event: React.PointerEvent<HTMLInputElement>) {
    if (!isPrimaryPress(event)) {
      return;
    }
    if (isFocused(event.currentTarget)) {
      return;
    }
    const position = positionOf(volume);
    dragStart.current = { x: event.clientX, position };
    hasDragged.current = false;
  }

  function drag(event: React.PointerEvent<HTMLInputElement>) {
    const start = dragStart.current;
    if (!start) {
      return;
    }
    if (isReleased(event)) {
      cancelDrag();
      return;
    }
    const travelled = event.clientX - start.x;
    const distance = Math.abs(travelled);
    const isStillAClick = !hasDragged.current && distance < DRAG_THRESHOLD_PX;
    if (isStillAClick) {
      return;
    }
    if (!hasDragged.current) {
      hasDragged.current = true;
      event.currentTarget.setPointerCapture(event.pointerId);
      setIsScrubbing(true);
    }
    const stops = travelled / PX_PER_STOP;
    const position = start.position + stops;
    const next = volumeAt(position);
    if (next !== volume) {
      onScrub(next);
    }
  }

  function endDrag(event: React.PointerEvent<HTMLInputElement>) {
    const start = dragStart.current;
    dragStart.current = null;
    if (!start) {
      return;
    }
    if (hasDragged.current) {
      setIsScrubbing(false);
      return;
    }
    const input = event.currentTarget;
    input.focus();
    input.select();
  }

  function cancelDrag() {
    dragStart.current = null;
    setIsScrubbing(false);
  }

  function rememberVolume(event: React.FocusEvent<HTMLInputElement>) {
    volumeAtFocus.current = volume;
    event.currentTarget.select();
  }

  function type(event: React.ChangeEvent<HTMLInputElement>) {
    onType(event.currentTarget.value);
  }

  function pressKey(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      onScrub(stopAbove(volume));
      return;
    }
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      onScrub(stopBelow(volume));
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      onCommit();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onScrub(volumeAtFocus.current);
      onCommit();
    }
  }

  return (
    <div className='flex flex-col'>
      <p className='text-3xl leading-tight font-semibold text-balance @2xl:text-4xl @4xl:text-5xl'>
        I expect{' '}
        <span className='relative inline-grid align-baseline'>
          <span
            aria-hidden='true'
            className='invisible col-start-1 row-start-1 px-2 whitespace-pre tabular-nums'
          >
            {shownText}
          </span>
          <input
            type='text'
            size={1}
            maxLength={MAX_TYPED_CHARACTERS}
            inputMode='numeric'
            autoComplete='off'
            spellCheck={false}
            aria-label='Requests you expect each month'
            aria-describedby={describedByOf(isOverLimit, hintId)}
            data-scrubbing={scrubbingOf(isHandOnNumber)}
            value={shownText}
            onChange={type}
            onFocus={rememberVolume}
            onBlur={onCommit}
            onKeyDown={pressKey}
            onMouseDown={keepFocusAway}
            onPointerDown={startDrag}
            onPointerMove={drag}
            onPointerUp={endDrag}
            onPointerCancel={cancelDrag}
            className='bg-primary/10 text-primary-ink hover:bg-primary/15 focus-visible:ring-ring/25 data-scrubbing:bg-primary/20 col-start-1 row-start-1 w-full min-w-0 cursor-ew-resize touch-pan-y rounded-xl px-2 tabular-nums transition-[background-color,box-shadow] duration-150 outline-none focus:cursor-text focus-visible:ring-[3px]'
          />
        </span>{' '}
        requests a month
      </p>
      <AnimatePresence initial={false}>
        {isOverLimit && (
          <motion.p
            key='over'
            id={hintId}
            {...presence}
            className='text-warning-foreground overflow-hidden text-[13px] text-pretty'
          >
            <span className='block pt-3'>{SECTION.over}</span>
          </motion.p>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import type { CSSProperties } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Slider } from '@/registry/ndeko/ui/slider';

import type { Plan } from './data';
import {
  formatVolume,
  LAST_POSITION,
  NOTCHES,
  positionOf,
  shareOf,
  volumeAt,
  type Zone,
  ZONES,
} from './volume-model';

const ZONE_INK =
  'text-muted-foreground transition-colors duration-200 data-current:text-foreground data-current:font-medium';

function amountOf(value: number | readonly number[]) {
  if (typeof value === 'number') {
    return value;
  }
  return value[0];
}

/** A zero-width anchor moved by a share of the row: it never widens the page. */
function anchorStyleOf(share: number): CSSProperties {
  const percent = share * 100;
  return { transform: `translateX(${percent}cqw)` };
}

function zoneCenterOf(zone: Zone) {
  const sum = zone.from + zone.to;
  const middle = sum / 2;
  return shareOf(middle);
}

function currentOf(isCurrent: boolean) {
  if (isCurrent) {
    return '';
  }
  return undefined;
}

/** Notches drawn across the track where another plan becomes the cheapest; the track paints over their middle. */
function TrackNotches() {
  return (
    <div
      aria-hidden='true'
      className='@container pointer-events-none absolute inset-x-0 top-1/2 h-3 -translate-y-1/2'
    >
      {NOTCHES.map((notch) => {
        const share = shareOf(notch.position);
        return (
          <span
            key={notch.volume}
            style={anchorStyleOf(share)}
            className='absolute inset-y-0 left-0 w-0'
          >
            <span className='bg-foreground/35 absolute inset-y-0 left-0 w-px -translate-x-1/2' />
          </span>
        );
      })}
    </div>
  );
}

function ZoneNames({ cheapest }: { cheapest: Plan }) {
  return (
    <div aria-hidden='true' className='@container relative h-5'>
      {ZONES.map((zone) => {
        const center = zoneCenterOf(zone);
        const isCurrent = zone.plan === cheapest;
        return (
          <span
            key={zone.from}
            style={anchorStyleOf(center)}
            className='absolute top-0 left-0 w-0'
          >
            <span
              data-current={currentOf(isCurrent)}
              className={cn(
                'absolute top-0 left-0 -translate-x-1/2 text-xs whitespace-nowrap',
                ZONE_INK
              )}
            >
              {zone.plan.name}
            </span>
          </span>
        );
      })}
    </div>
  );
}

type VolumeTrackProps = {
  volume: number;
  cheapest: Plan;
  onVolumeChange: (volume: number) => void;
};

/** The same volume on a log track, with a notch wherever the cheapest plan changes and the plan named on each stretch. */
export function VolumeTrack({
  volume,
  cheapest,
  onVolumeChange,
}: VolumeTrackProps) {
  const position = positionOf(volume);
  const spokenVolume = formatVolume(volume);

  function change(value: number | readonly number[]) {
    const nextPosition = amountOf(value);
    const next = volumeAt(nextPosition);
    onVolumeChange(next);
  }

  function spokenValueOf() {
    return `${spokenVolume} requests a month, ${cheapest.name} is the cheapest`;
  }

  return (
    <div className='flex flex-col gap-1.5'>
      <div className='relative'>
        <TrackNotches />
        <Slider
          value={position}
          min={0}
          max={LAST_POSITION}
          step={1}
          thumbLabels={['Requests a month']}
          getAriaValueText={spokenValueOf}
          onValueChange={change}
        />
      </div>
      <ZoneNames cheapest={cheapest} />
    </div>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Wash } from '@/registry/ndeko/ui/wash';

import type { Plan } from './data';
import {
  costOf,
  formatPrice,
  formatRate,
  formatVolume,
  PRICE_FORMAT,
} from './volume-model';

const RESTING_SURFACE =
  'bg-card hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const LIFTED_SURFACE = 'surface-brand -translate-y-1';

const CHIP_SHOWN = { opacity: 1, scale: 1 };

const CHIP_HIDDEN = { opacity: 0, scale: 0.95 };

const CHIP_FADE = { opacity: 0 };

const CHIP_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

function surfaceOf(isCheapest: boolean) {
  if (isCheapest) {
    return LIFTED_SURFACE;
  }
  return RESTING_SURFACE;
}

function actionVariantOf(isCheapest: boolean) {
  if (isCheapest) {
    return 'default' as const;
  }
  return 'outline' as const;
}

function chipHiddenOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return CHIP_FADE;
  }
  return CHIP_HIDDEN;
}

type PlanCardProps = {
  plan: Plan;
  volume: number;
  isCheapest: boolean;
};

/** One plan priced for the volume of the sentence; the cheapest one lifts out of the row. */
export function PlanCard({ plan, volume, isCheapest }: PlanCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const cost = costOf(plan, volume);
  const price = Math.round(cost);
  const basePrice = formatPrice(plan.basePrice);
  const included = formatVolume(plan.includedRequests);
  const rate = formatRate(plan.pricePerThousand);
  const chipHidden = chipHiddenOf(shouldReduceMotion);

  return (
    <article
      className={cn(
        'relative isolate flex flex-col gap-5 rounded-xl p-5 transition-[translate,box-shadow] duration-300 ease-(--ease-out-strong)',
        surfaceOf(isCheapest)
      )}
    >
      <Wash isShown={isCheapest} />
      <div className='flex flex-col gap-1'>
        <div className='flex min-h-5 items-center justify-between gap-2'>
          <h3 className='text-sm font-medium'>{plan.name}</h3>
          <AnimatePresence initial={false}>
            {isCheapest && (
              <motion.span
                key='cheapest'
                initial={chipHidden}
                animate={CHIP_SHOWN}
                exit={chipHidden}
                transition={CHIP_TRANSITION}
                className='inline-flex'
              >
                <Chip>Cheapest for you</Chip>
              </motion.span>
            )}
          </AnimatePresence>
        </div>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {plan.summary}
        </p>
      </div>
      <p className='flex items-baseline gap-1.5'>
        <MotionNumber
          value={price}
          format={PRICE_FORMAT}
          className='text-4xl font-semibold'
        />
        <span className='text-muted-foreground text-[13px]'>a month</span>
      </p>
      <ul className='text-muted-foreground flex flex-col gap-1 text-xs tabular-nums'>
        <li>{basePrice} base price</li>
        <li>{included} requests included</li>
        <li>{rate} per 1,000 after that</li>
      </ul>
      <Button
        size='lg'
        variant={actionVariantOf(isCheapest)}
        nativeButton={false}
        render={<a href='#' />}
        className='mt-auto'
      >
        {plan.action}
      </Button>
    </article>
  );
}

import { MAX_VOLUME, type Plan, PLANS, STOPS } from './data';

/** A place on the track where another plan becomes the cheapest. */
export type Notch = {
  volume: number;
  position: number;
  plan: Plan;
};

/** The stretch of the track where one plan is the cheapest. */
export type Zone = {
  plan: Plan;
  from: number;
  to: number;
};

export const LAST_POSITION = STOPS.length - 1;

const FIRST_STOP = STOPS[0];

export const PRICE_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const PRICE_FORMATTER = new Intl.NumberFormat('en-US', PRICE_FORMAT);

const RATE_FORMATTER = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

const VOLUME_FORMATTER = new Intl.NumberFormat('en-US');

const NOT_DIGITS = /\D/g;

export function formatPrice(amount: number) {
  return PRICE_FORMATTER.format(amount);
}

export function formatRate(amount: number) {
  return RATE_FORMATTER.format(amount);
}

export function formatVolume(volume: number) {
  return VOLUME_FORMATTER.format(volume);
}

/** The number in a typed text, whatever separators came with it; null while nothing is typed. */
export function volumeOfText(text: string) {
  const digits = text.replace(NOT_DIGITS, '');
  if (digits === '') {
    return null;
  }
  return Number(digits);
}

export function clampVolume(volume: number) {
  const atLeastZero = Math.max(volume, 0);
  return Math.min(atLeastZero, MAX_VOLUME);
}

export function costOf(plan: Plan, volume: number) {
  const over = volume - plan.includedRequests;
  const billable = Math.max(0, over);
  const thousands = billable / 1_000;
  const overage = thousands * plan.pricePerThousand;
  return plan.basePrice + overage;
}

/** The plan that costs the least for this volume. A tie goes to the smaller plan. */
export function cheapestPlanAt(volume: number) {
  let cheapest = PLANS[0];
  let lowest = costOf(cheapest, volume);
  for (const plan of PLANS) {
    const cost = costOf(plan, volume);
    if (cost < lowest) {
      cheapest = plan;
      lowest = cost;
    }
  }
  return cheapest;
}

/** Where a volume sits on the track: on a stop, or between two stops on a log scale. */
export function positionOf(volume: number) {
  if (volume <= FIRST_STOP) {
    return 0;
  }
  for (let index = 0; index < LAST_POSITION; index += 1) {
    const low = STOPS[index];
    const high = STOPS[index + 1];
    if (volume <= high) {
      const covered = Math.log(volume / low);
      const span = Math.log(high / low);
      const along = covered / span;
      return index + along;
    }
  }
  return LAST_POSITION;
}

export function volumeAt(position: number) {
  const index = Math.round(position);
  const atLeastFirst = Math.max(index, 0);
  const bounded = Math.min(atLeastFirst, LAST_POSITION);
  return STOPS[bounded];
}

export function shareOf(position: number) {
  return position / LAST_POSITION;
}

/** The arrow keys go from stop to stop, starting from any typed volume. */
export function stopAbove(volume: number) {
  const stop = STOPS.find((candidate) => candidate > volume);
  if (stop === undefined) {
    return MAX_VOLUME;
  }
  return stop;
}

/** Under the first stop there is nowhere lower to go, so a typed 300 stays 300 instead of rising to it. */
export function stopBelow(volume: number) {
  const lower = STOPS.filter((candidate) => candidate < volume);
  const stop = lower.at(-1);
  if (stop === undefined) {
    return volume;
  }
  return stop;
}

/** The smallest volume past `low` where the cheapest plan is no longer the one at `low`. */
function firstVolumeOfChange(low: number, high: number) {
  const before = cheapestPlanAt(low);
  let below = low;
  let above = high;
  while (above - below > 1) {
    const sum = below + above;
    const middle = Math.floor(sum / 2);
    const plan = cheapestPlanAt(middle);
    if (plan === before) {
      below = middle;
    } else {
      above = middle;
    }
  }
  return above;
}

function notchesOf() {
  const notches: Notch[] = [];
  for (let index = 0; index < LAST_POSITION; index += 1) {
    const low = STOPS[index];
    const high = STOPS[index + 1];
    const lowPlan = cheapestPlanAt(low);
    const highPlan = cheapestPlanAt(high);
    if (lowPlan === highPlan) {
      continue;
    }
    const volume = firstVolumeOfChange(low, high);
    const position = positionOf(volume);
    notches.push({ volume, position, plan: highPlan });
  }
  return notches;
}

function zonesOf(notches: readonly Notch[]) {
  const zones: Zone[] = [];
  let from = 0;
  let plan = cheapestPlanAt(FIRST_STOP);
  for (const notch of notches) {
    zones.push({ plan, from, to: notch.position });
    from = notch.position;
    plan = notch.plan;
  }
  zones.push({ plan, from, to: LAST_POSITION });
  return zones;
}

/** The prices are fixed, so the places where the cheapest plan changes are worked out once. */
export const NOTCHES = notchesOf();

export const ZONES = zonesOf(NOTCHES);

